/**
 * Demon Slayer Transition Animation
 * - The Comedic transition animation from demon slayer reimagined
 * 
 * Note: by default, if you have not tokens selected it will use player's character token images
 *  otherwise it will use the token images of your selected tokens
 * SETTINGS
 * useConfig - Set to true to use the config below
 * Config - can be used to set specific settings of the animation
 *  bg - Background art
 *  art - Array of art of the characters to go accross the screen
 *  useCharacters - Forces to use the characters the players have set on their user
 *  duration - Duration of the animation in MS
 *  sfx - SFX to play with the animation
 *  volume - volume to play the SFX at
 *  sfxDelay - How long in MS to wait before playing the sfx
 */
const useConfig = false;
const config = {
    bg: "modules/genga/assets/demon-slayer-transitions/scuffed_DS_Transition_BG.webp",
    art: ["icons/logo-scifi-blank.png", "icons/vtt-512.png", "icons/logo-scifi.png"],
    useCharacters: false,
    duration: 2500,
    sfx: "modules/genga/assets/demon-slayer-transitions/bongo-drum-roll.ogg",
    volume: 0.5,
    sfxDelay: 0,
}
if (!useConfig) {
    game.genga.api.demonSlayerTransition();
} else {
    game.genga.api.demonSlayerTransition(config);
}
